import { describe, it, expect, beforeEach, vi } from 'vitest'
import {
  CADEMirror,
  type MirrorNegotiation,
  type CounterpartyRoster,
  type OpposedMove,
  type Divergence,
} from '../mirror-negotiation'

type MockInvoker = ReturnType<typeof vi.fn>

describe('CADE Mirror Negotiation', () => {
  let mirror: CADEMirror
  let mockInvoker: MockInvoker

  beforeEach(() => {
    mockInvoker = vi.fn()
    mirror = new CADEMirror({
      invoker: mockInvoker,
      tribunalModel: 'local:llama3.2:3b',
    })
  })

  describe('initialization', () => {
    it('should initialize with counterparty roster', () => {
      const roster: CounterpartyRoster = {
        adversaries: ['legal-counsel', 'competitor', 'regulator'],
        objectives: {
          'legal-counsel': 'minimize liability exposure',
          competitor: 'block market expansion',
          regulator: 'ensure compliance',
        },
      }
      const mirrorWithRoster = new CADEMirror({
        invoker: mockInvoker,
        roster,
        tribunalModel: 'local:llama3.2:3b',
      })
      expect(mirrorWithRoster.getRoster()).toEqual(roster)
    })

    it('should default to empty roster if not provided', () => {
      expect(mirror.getRoster().adversaries).toEqual([])
    })
  })

  describe('mirror negotiation flow', () => {
    it('should return opposed move for a proposed action', async () => {
      const proposedMove = {
        action: 'launch enterprise tier',
        rationale: 'expand market reach',
        constraints: ['legal review required'],
      }

      mockInvoker.mockResolvedValue({
        opposedMove: {
          action: 'delay launch until Q4',
          adversary: 'legal-counsel',
          strength: 0.85,
          reasoning: 'H1 regulatory timeline incomplete',
        },
        divergence: {
          scoreProposed: 0.72,
          scoreOpposed: 0.65,
          delta: -0.07,
          criticalGaps: ['compliance attestation', 'liability cap'],
        },
      })

      const result = await mirror.negotiate(proposedMove)

      expect(result.opposedMove).toBeDefined()
      expect(result.opposedMove.adversary).toBe('legal-counsel')
      expect(result.divergence).toBeDefined()
      expect(result.divergence.delta).toBeLessThan(0)
    })

    it('should identify strongest counterparty position', async () => {
      const proposedMove = {
        action: 'aggressive pricing strategy',
        rationale: 'capture market share',
      }

      mockInvoker.mockResolvedValue({
        opposedMove: {
          action: 'maintain premium positioning',
          adversary: 'competitor',
          strength: 0.92,
          reasoning: 'undercuts brand equity',
        },
        divergence: {
          scoreProposed: 0.68,
          scoreOpposed: 0.78,
          delta: 0.1,
          criticalGaps: ['margin erosion', 'brand dilution'],
        },
      })

      const result = await mirror.negotiate(proposedMove)

      expect(result.opposedMove.strength).toBeGreaterThan(0.9)
      expect(result.divergence.delta).toBeGreaterThan(0)
    })
  })

  describe('divergence analysis', () => {
    it('should calculate divergence between proposed and opposed moves', async () => {
      mockInvoker.mockResolvedValue({
        opposedMove: {
          action: 'conservative scaling',
          adversary: 'regulator',
          strength: 0.74,
        },
        divergence: {
          scoreProposed: 0.8,
          scoreOpposed: 0.65,
          delta: -0.15,
          criticalGaps: ['data residency', 'audit trails'],
        },
      })

      const result = await mirror.negotiate({ action: 'aggressive expansion' })

      expect(result.divergence.scoreProposed).toBeDefined()
      expect(result.divergence.scoreOpposed).toBeDefined()
      expect(result.divergence.delta).toBeDefined()
    })

    it('should identify critical gaps in proposed move', async () => {
      const gaps = ['compliance', 'scalability', 'security']
      mockInvoker.mockResolvedValue({
        opposedMove: { action: 'revised plan', adversary: 'internal-security' },
        divergence: {
          scoreProposed: 0.55,
          scoreOpposed: 0.72,
          delta: 0.17,
          criticalGaps: gaps,
        },
      })

      const result = await mirror.negotiate({ action: 'deploy system' })

      expect(result.divergence.criticalGaps).toEqual(gaps)
    })
  })

  describe('war-room intelligence panel', () => {
    it('should format mirror result for intelligence panel', async () => {
      mockInvoker.mockResolvedValue({
        opposedMove: {
          action: 'pivot strategy',
          adversary: 'market-force',
          strength: 0.81,
          reasoning: 'demand softening detected',
        },
        divergence: {
          scoreProposed: 0.7,
          scoreOpposed: 0.76,
          delta: 0.06,
          criticalGaps: ['market timing', 'customer retention'],
        },
      })

      const result = await mirror.negotiate({ action: 'aggressive launch' })
      const panelData = mirror.formatForIntelligencePanel(result)

      expect(panelData).toHaveProperty('proposedMove')
      expect(panelData).toHaveProperty('opposedMove')
      expect(panelData).toHaveProperty('divergence')
      expect(panelData).toHaveProperty('timestamp')
    })

    it('should include adversary profile in panel output', async () => {
      mockInvoker.mockResolvedValue({
        opposedMove: {
          action: 'hold position',
          adversary: 'regulatory-body',
          strength: 0.88,
        },
        divergence: {
          scoreProposed: 0.65,
          scoreOpposed: 0.75,
          delta: 0.1,
          criticalGaps: [],
        },
      })

      const result = await mirror.negotiate({ action: 'move' })
      const panelData = mirror.formatForIntelligencePanel(result)

      expect(panelData.opposedMove.adversary).toBe('regulatory-body')
      expect(panelData.opposedMove.strength).toBe(0.88)
    })
  })

  describe('tribunal model adjudication', () => {
    it('should invoke tribunal model for complex tradeoffs', async () => {
      mockInvoker.mockResolvedValue({
        opposedMove: {
          action: 'balanced approach',
          adversary: 'tribunal',
          strength: 0.79,
        },
        divergence: {
          scoreProposed: 0.71,
          scoreOpposed: 0.74,
          delta: 0.03,
          criticalGaps: ['stakeholder alignment'],
        },
        tribunalJudgment: {
          winner: 'hybrid',
          reasoning: 'proposed move viable with modifications',
          modifications: ['add stakeholder review', 'phase rollout'],
        },
      })

      const result = await mirror.negotiate(
        { action: 'full deployment' },
        { useTribunal: true }
      )

      expect(result.tribunalJudgment).toBeDefined()
      expect(result.tribunalJudgment.winner).toBeDefined()
    })

    it('should provide tribunal modifications for proposed move', async () => {
      mockInvoker.mockResolvedValue({
        opposedMove: { action: 'alternative', adversary: 'tribunal' },
        divergence: {
          scoreProposed: 0.68,
          scoreOpposed: 0.72,
          delta: 0.04,
          criticalGaps: [],
        },
        tribunalJudgment: {
          winner: 'proposed-with-conditions',
          reasoning: 'move acceptable with safeguards',
          modifications: [
            'implement audit logging',
            'establish rollback plan',
            'set success metrics',
          ],
        },
      })

      const result = await mirror.negotiate(
        { action: 'release feature' },
        { useTribunal: true }
      )

      expect(result.tribunalJudgment.modifications).toHaveLength(3)
    })
  })

  describe('edge cases and error handling', () => {
    it('should handle empty counterparty roster gracefully', async () => {
      const emptyMirror = new CADEMirror({
        invoker: mockInvoker,
        roster: { adversaries: [], objectives: {} },
        tribunalModel: 'local:llama3.2:3b',
      })

      mockInvoker.mockResolvedValue({
        opposedMove: {
          action: 'no opposition',
          adversary: 'none',
          strength: 0,
        },
        divergence: {
          scoreProposed: 1.0,
          scoreOpposed: 0,
          delta: -1.0,
          criticalGaps: [],
        },
      })

      const result = await emptyMirror.negotiate({ action: 'uncontested' })
      expect(result).toBeDefined()
    })

    it('should handle missing proposed move constraints', async () => {
      mockInvoker.mockResolvedValue({
        opposedMove: { action: 'counter', adversary: 'unknown' },
        divergence: {
          scoreProposed: 0.5,
          scoreOpposed: 0.5,
          delta: 0,
          criticalGaps: ['missing context'],
        },
      })

      const result = await mirror.negotiate({ action: 'minimal move' })
      expect(result.divergence.criticalGaps).toContain('missing context')
    })

    it('should handle invoker failure gracefully', async () => {
      mockInvoker.mockRejectedValue(new Error('Invoker unavailable'))

      await expect(
        mirror.negotiate({ action: 'test move' })
      ).rejects.toThrow('Invoker unavailable')
    })

    it('should validate opposed move strength is between 0 and 1', async () => {
      mockInvoker.mockResolvedValue({
        opposedMove: {
          action: 'counter',
          adversary: 'test',
          strength: 0.85,
        },
        divergence: {
          scoreProposed: 0.7,
          scoreOpposed: 0.75,
          delta: 0.05,
          criticalGaps: [],
        },
      })

      const result = await mirror.negotiate({ action: 'move' })
      expect(result.opposedMove.strength).toBeGreaterThanOrEqual(0)
      expect(result.opposedMove.strength).toBeLessThanOrEqual(1)
    })
  })

  describe('multiple counterparty analysis', () => {
    it('should rank counterparty positions by strength', async () => {
      const roster: CounterpartyRoster = {
        adversaries: ['legal', 'competitor', 'regulator'],
        objectives: {
          legal: 'minimize risk',
          competitor: 'block growth',
          regulator: 'enforce compliance',
        },
      }

      mockInvoker.mockResolvedValue({
        opposedMoves: [
          {
            action: 'delay launch',
            adversary: 'legal',
            strength: 0.92,
          },
          {
            action: 'undercut pricing',
            adversary: 'competitor',
            strength: 0.78,
          },
          {
            action: 'require audit',
            adversary: 'regulator',
            strength: 0.81,
          },
        ],
        opposedMove: {
          action: 'delay launch',
          adversary: 'legal',
          strength: 0.92,
        },
        divergence: {
          scoreProposed: 0.65,
          scoreOpposed: 0.80,
          delta: 0.15,
          criticalGaps: ['legal review', 'compliance'],
        },
      })

      const mirrorWithRoster = new CADEMirror({
        invoker: mockInvoker,
        roster,
        tribunalModel: 'local:llama3.2:3b',
      })

      const result = await mirrorWithRoster.negotiate({ action: 'launch' })
      expect(result.opposedMove.strength).toBe(0.92)
    })
  })

  describe('negotiation history', () => {
    it('should track negotiation history for analysis', async () => {
      mockInvoker.mockResolvedValue({
        opposedMove: {
          action: 'first counter',
          adversary: 'test1',
          strength: 0.7,
        },
        divergence: {
          scoreProposed: 0.6,
          scoreOpposed: 0.7,
          delta: 0.1,
          criticalGaps: [],
        },
      })

      await mirror.negotiate({ action: 'first move' })
      mockInvoker.mockResolvedValue({
        opposedMove: {
          action: 'second counter',
          adversary: 'test2',
          strength: 0.8,
        },
        divergence: {
          scoreProposed: 0.65,
          scoreOpposed: 0.75,
          delta: 0.1,
          criticalGaps: [],
        },
      })

      await mirror.negotiate({ action: 'second move' })

      const history = mirror.getHistory()
      expect(history).toHaveLength(2)
      expect(history[0].opposedMove.action).toBe('first counter')
      expect(history[1].opposedMove.action).toBe('second counter')
    })
  })

  describe('integration with war-room panel', () => {
    it('should provide real-time intelligence updates', async () => {
      mockInvoker.mockResolvedValue({
        opposedMove: {
          action: 'pivot',
          adversary: 'market',
          strength: 0.82,
          reasoning: 'demand shift detected',
        },
        divergence: {
          scoreProposed: 0.71,
          scoreOpposed: 0.75,
          delta: 0.04,
          criticalGaps: ['market timing'],
        },
      })

      const result = await mirror.negotiate({ action: 'launch now' })
      const panel = mirror.formatForIntelligencePanel(result)

      expect(panel.timestamp).toBeDefined()
      expect(panel.opposedMove.reasoning).toContain('demand')
      expect(panel.divergence.criticalGaps).toContain('market timing')
    })
  })
})
